insert into public.portfolio_projects(id,title,description,intro,story,approach,status_note,tags,cover_url,cover_color,gallery,repository_url,demo_url,published,archived,sort_order) values('news','AI News Reader','Turning headlines into a listening experience.','An exploration in making news easier to listen to, with an Android app, a Wear OS companion, and a separate web reader.','The project brings topic-based headlines into an audio-oriented interface. The phone handles news and playback; the watch provides compact controls. A web companion explores the same listening workflow in the browser.','A pipeline connects news retrieval, AI-assisted summaries, and speech synthesis. The watch exchanges playback state and commands with its paired phone through the Wearable API.','Prototype. The documented watch captures use labeled sample state. Provider availability, paired-device behavior, and successful end-to-end playback remain limitations documented in the repository.',array['Kotlin','Android','Wear OS','Gemini','Text-to-speech'],'/assets/news-watch.png','lilac','[]'::jsonb,'https://github.com/Sanju2911/AI-news-reader','',true,false,0);
insert into public.portfolio_projects(id,title,description,intro,story,approach,status_note,tags,cover_url,cover_color,gallery,repository_url,demo_url,published,archived,sort_order) values('creator','Creator’s Tool','One workspace for the messy creative process.','A creative workspace that keeps references, script writing, and visual storyboards within one flow.','Creative ideas often live across saved links, notes, and disconnected tools. This project brings account workspaces, references, scripts, and storyboards into one interface.','The React application combines a reference library, script editor, and canvas drawing tools. Express supports profile retrieval, while Supabase and browser-local storage provide persistence paths.','Local development application. Authentication fallback, shared creative libraries, and persistence limitations are documented in the repository. Screenshots have personal identities masked.',array['React','Express','Supabase','HTML Canvas'],'/assets/creator-workspace.jpg','mint','[]'::jsonb,'https://github.com/Sanju2911/CreatorsTool-Insta','',true,false,1);
insert into public.portfolio_projects(id,title,description,intro,story,approach,status_note,tags,cover_url,cover_color,gallery,repository_url,demo_url,published,archived,sort_order) values('cli','belazywithreact','A faster start for your next React idea.','A Python command-line tool that turns the repetitive first steps of a React project into a configurable starting point.','The interesting part of an application rarely starts with configuring the same tools again. This CLI creates a React + TypeScript app and connects a selection of starter tools.','Options cover styling, routing, API utilities, state management, formatting, linting, and tests. The implementation validates project names and destinations, checks prerequisites, and preserves existing directories.','Source, tests, CI configuration, and packaging files are available. The terminal shown here is an illustrative command sequence, not a recording of a live installation.',array['Python','Typer','React','TypeScript','Vite'],'','peach','[]'::jsonb,'https://github.com/Sanju2911/belazywithreact','',true,false,2);
insert into public.portfolio_projects(id,title,description,intro,story,approach,status_note,tags,cover_url,cover_color,gallery,repository_url,demo_url,published,archived,sort_order) values('trip','Trip Planner','Less planning chaos. More going places.','A group trip planning prototype for turning scattered conversations into a shared plan.','Dates, meeting points, itineraries, expenses, and packing details can be hard to keep together. Trip Planner organizes those details around a calendar and a guided trip workflow.','The interface includes a five-step trip wizard and views for multi-day activities, group coordination, expenses, and checklists. React handles the interface with Supabase integrations for data and media.','Portfolio/demo application. The committed screenshots use fictional intercepted API responses. Current authentication and live backend limitations are documented; this is not presented as a production service.',array['React','Supabase','Calendar','Group planning'],'/assets/trip-dashboard.png','yellow','[]'::jsonb,'https://github.com/Sanju2911/trip-planner','',true,false,3);
